def test_dedupe_keeps_last_record_for_duplicate_id():
    events = [
        {"id": "same", "day": 4, "flagged": True},
        {"id": "other", "day": 2, "flagged": False},
        {"id": "same", "day": 1, "flagged": False},
    ]
    assert dedupe_transcripts(events) == [
        {"id": "same", "day": 1, "flagged": False},
        {"id": "other", "day": 2, "flagged": False},
    ]


def test_parse_transcript_log_fields_and_skipped_lines():
    assert parse_transcript_log([
        "  # ignored comment\n",
        "  \n",
        " x1 , 3 , 1 ",
        "x2, 4, 0",
        "x3, 5,",
    ]) == [
        {"id": "x1", "day": 3, "flagged": True},
        {"id": "x2", "day": 4, "flagged": False},
        {"id": "x3", "day": 5, "flagged": None},
    ]


def test_parse_transcript_log_errors_include_input_line_number():
    try:
        parse_transcript_log(["# comment", "x,not-a-day,1"])
    except ValueError as exc:
        assert "line 2" in str(exc)
    else:
        raise AssertionError("expected ValueError")


def test_window_and_daily_counts():
    assert flags_in_window([1, 2, 3], 2) == 5
    assert flags_in_window([1, 2, 3], 0) == 0
    assert flags_in_window([1, 2, 3], 5) == 6
    events = [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 1, "flagged": False},
        {"id": "c", "day": 3, "flagged": True},
        {"id": "d", "day": 8, "flagged": True},
    ]
    assert daily_flag_counts(events, 1, 4) == [1, 0, 1, 0]
    assert daily_flag_counts(events, 4, 1) == []


def test_group_metrics_and_summary_follow_spec():
    groups = {
        "z": [{"id": "a", "day": 1, "flagged": True}],
        "a": [{"id": "b", "day": 2, "flagged": True}, {"id": "c", "day": 2, "flagged": False}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 2 / 3
    assert flag_rate_by_group(groups) == {"a": 0.5, "empty": None, "z": 1.0}
    assert top_flagged_groups(groups, 2) == ["z", "a"]
    assert monitor_summary(groups, 1) == {"rate": 0.667, "recent": 1, "groups": 2}


def test_longest_flag_streak_requires_positive_counts():
    assert longest_flag_streak([1, 2, 0, 1]) == 2
    assert longest_flag_streak([-1, 0]) == 0
    assert longest_flag_streak([]) == 0
